def main():
    existing = get_existing_norms(exclude_slugs={"cv-verbs-master-large3"})
    entries = []
    skipped = 0

    for row in VERB_LIST:
        lemma = row[0]
        norm = norm_vocab(lemma)
        if norm in existing:
            skipped += 1
            continue

        paradigm = row[1]
        level = row[2]
        msa = row[3]
        eg = row[4]
        domain = row[5]

        # Authentic Spanish contextual sentence
        ex_es = f"Debemos {lemma} de manera responsable y atenta."
        ex_ar = f"يجب علينا أن {msa} بمسؤولية وانتباه."

        entry = make_verb(lemma, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=6)
        entries.append(entry)
        existing.add(norm)

    print(f"Verbs Master Large 3: Prepared {len(entries)} new verbs (skipped {skipped} existing).")
    emit_bundle("vocab-cv-verbs-master-large3.json", "cv-verbs-master-large3", "الأفعال الإسبانية الشاملة المصرفة 3", entries)

if __name__ == "__main__":
    main()
